<?php defined('BASEPATH') OR exit('No direct script access allowed');$labels=['pending'=>['Menunggu verifikasi','yellow'],'approved'=>['Disetujui','green'],'rejected'=>['Ditolak','red'],'wa_sent'=>['Tautan WA dikirim','blue']]; ?>
<div class="page-header"><div class="container-xl"><div class="row align-items-center"><div class="col"><div class="page-pretitle">Membership · Keamanan Akun</div><h1 class="page-title">Verifikasi Reset Password</h1><p class="text-secondary mb-0">Jalur cadangan bagi member yang tidak menerima tautan WhatsApp.</p></div><div class="col-auto"><a href="<?=base_url('members');?>" class="btn btn-outline-secondary"><i class="ti ti-arrow-left me-1"></i>Data Member</a></div></div></div></div>
<div class="page-body"><div class="container-xl"><?php if($s=$this->session->flashdata('success')):?><div class="alert alert-success"><?=html_escape($s);?></div><?php endif;?><?php if($e=$this->session->flashdata('error')):?><div class="alert alert-danger"><?=html_escape($e);?></div><?php endif;?><div class="alert alert-warning"><i class="ti ti-shield-check me-1"></i>Pastikan identitas dan nomor anggota sesuai sebelum menyetujui. Persetujuan akan mengganti password akun dan menampilkannya selama 24 jam pada halaman status pemohon.</div><div class="card"><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Permintaan</th><th>Member</th><th>Kontak</th><th>Status</th><th>Proses</th></tr></thead><tbody><?php foreach($rows as $row):$state=$labels[$row['approval_status']]??['Diproses','secondary'];?><tr><td><strong><?=html_escape($row['request_code']);?></strong><small class="d-block text-secondary"><?=html_escape($row['created_at']);?></small></td><td><strong><?=html_escape($row['full_name']);?></strong><small class="d-block text-secondary">@<?=html_escape($row['username']);?> · <?=html_escape($row['member_no']??'-');?></small><small class="d-block text-secondary">NIK <?=html_escape($row['identity_number']??'-');?></small></td><td><?=html_escape($row['phone_number']);?><small class="d-block text-secondary">WA: <?=html_escape($row['wa_status']??'Tidak terkirim');?></small></td><td><span class="badge bg-<?=$state[1];?>-lt"><?=html_escape($state[0]);?></span><?php if(!empty($row['review_note'])):?><small class="d-block mt-1 text-secondary"><?=html_escape($row['review_note']);?></small><?php endif;?></td><td><?php if($row['approval_status']==='pending'):?><?=form_open('members/review_password_reset/'.(int)$row['id'],['class'=>'d-flex gap-2 align-items-center']);?><input class="form-control form-control-sm" name="review_note" maxlength="500" placeholder="Catatan verifikasi (opsional)"><button class="btn btn-sm btn-success" name="action" value="approve" data-confirm="Identitas pemohon sudah diverifikasi dan password akun boleh diganti?" data-confirm-title="Setujui Reset Password"><i class="ti ti-check me-1"></i>Setujui</button><button class="btn btn-sm btn-outline-danger" name="action" value="reject" data-confirm="Tolak permintaan reset ini?" data-confirm-title="Tolak Reset Password"><i class="ti ti-x"></i></button><?=form_close();?><?php else:?><span class="text-secondary small"><?=!empty($row['reviewed_at'])?html_escape($row['reviewed_at']):'Tidak memerlukan verifikasi manual';?></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="card-body text-center text-secondary py-5"><i class="ti ti-inbox fs-1 d-block mb-2"></i>Belum ada permintaan reset password.</div><?php endif;?></div></div></div>
